const r=require('./round-fixes.js');
const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
['魅力社區可以拿多少錢','40萬元'],['魅力社區補助要自己出錢嗎','十分之一'],['魅力社區自籌款要多少','2萬元'],
['我們社區想做魅力社區要怎麼報名','公所'],['社區想辦魅力社區要先做什麼','公所'],['魅力社區計畫怎麼申請','LINE'],
['沒有成立協會可以申請魅力社區嗎','立案滿1年'],['新成立的協會可以申請魅力社區嗎','立案'],['未立案的團體可以提魅力社區嗎','立案'],['魅力社區誰可以申請','會務和財務正常'],
['魅力社區的錢可以買東西嗎','原則上不行'],['魅力社區可以出去玩嗎','參訪'],['魅力社區可以辦聚餐嗎','慶生餐宴'],
['魅力社區計畫書怎麼寫','附件2'],['魅力社區提案要寫什麼','經費概算'],['魅力社區申請表怎麼填','核轉'],
['魅力社區講師費多少','2,000元'],['魅力社區便當每人多少錢','90元'],
['魅力社區錢用錯會怎樣','停止這項計畫的補助1年'],['魅力社區的錢亂花會怎樣','繳回'],
['魅力社區防災補助多少','6萬元'],['魅力社區防災整備最多可以拿多少','24萬元'],
['社區發展協會可以同時申請魅力社區和社造點嗎','不重複補助'],['魅力社區補助可以重複申請嗎','重複'],['魅力社區的補助可不可以再向別的單位申請','重複'],
['魅力社區是什麼','6個面向'],['魅力計畫是什麼','經費補助'],['社造點是什麼','文化共創'],
['魅力社區做哪些方案可以過','社區環保'],['魅力社區核銷逾期怎麼辦','12月10日']];
const no=['合作社可以拿多少錢','魅力社區電話','魅力社區找誰','好讚認證沒過怎麼辦','協會可以買設備嗎','協會辦旅遊可以嗎','協會補助多少錢','怎麼申請成立協會','協會講師費多少','志工做錯事誰賠','協會核銷逾期怎麼辦'];
const mine=/^(魅力社區(?!計畫承辦人)|社造點是|想申請魅力社區)/;
let bad=0;
yes.forEach(([q,e])=>{const a=A(q);const x=a&&a.title?(a.title+a.summary):'';if(!x.includes(e)||!a.direct||!mine.test(a.title)){bad++;console.log('✗',q,a&&a.title)}});
no.forEach(q=>{const a=A(q);if(a&&a.title&&mine.test(a.title)){bad++;console.log('✗誤觸',q,a.title)}});
console.log(bad?'失敗 '+bad:'全部通過');process.exit(bad?1:0);
